import numpy as np
def solve(x,y,a,b):
 x,y=np.asarray(x,float),np.asarray(y,float)
 if x.ndim!=1 or y.shape!=x.shape or len(x)==0: raise ValueError("shape")
 return float(np.sum((a*x+b-y)**2)/(2*len(x)))

